parameters.jsCode:
const content = $input.item.json.content[0].text;
const jsonMatch = content.match(/\{\"intent\"[^}]+\}/);
let intent = { intent:'outro', servico:null, data_desejada:null, tipo_cobranca:null, cliente_pacote_id:null };
let resposta = content;
if (jsonMatch) {
  try {
    intent = JSON.parse(jsonMatch[0]);
    resposta = content.replace(jsonMatch[0], '').trim();
  } catch(e) {}
}
return [{ json: {
  resposta_ia:        resposta,
  intent:             intent.intent,
  servico:            intent.servico,
  data_desejada:      intent.data_desejada,
  tipo_cobranca:      intent.tipo_cobranca,
  cliente_pacote_id:  intent.cliente_pacote_id
}}];

